import RNA, random
from multiprocessing import Pool

s='.(((.(((...(((.(((...))).(((....))).)))...(((.(((....))).(((...))).)))...(((.(((....))).(((...))).)))...))).(((...))).))).'
N=len(s)
pairs=[]
stack=[]
for i,ch in enumerate(s):
    if ch=='(':
        stack.append(i)
    elif ch==')':
        j=stack.pop()
        pairs.append((j,i))
paired_pos=set()
for (i,j) in pairs:
    paired_pos.add(i);paired_pos.add(j)
unpaired=[i for i in range(N) if i not in paired_pos]

def bp_dist_str(mfe):
    a=[];st=[]
    for i,c in enumerate(mfe):
        if c=='(':st.append(i)
        elif c==')':a.append((st.pop(),i))
    return len(set(a)^set(pairs))

PAIRS=[('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
pair_idx={i:(i,j) for (i,j) in pairs}
pair_idx.update({j:(i,j) for (i,j) in pairs})

def run(args):
    seed,trial=args
    random.seed(trial)
    seq=list(seed)
    # light perturbation
    for i in range(N):
        if i in pair_idx:
            if random.random()<0.2:
                (pi,pj)=pair_idx[i]
                a,b=random.choice(PAIRS)
                seq[pi]=a;seq[pj]=b
        else:
            if random.random()<0.2:
                seq[i]=random.choice('ACGU')
    cur=''.join(seq)
    fc=RNA.fold_compound(cur)
    mfe,_=fc.mfe()
    d=bp_dist_str(mfe)
    best=cur[:];bestd=d
    T=1.5
    for step in range(5000):
        i=random.randrange(N)
        old=seq[i]
        if i in pair_idx:
            (pi,pj)=pair_idx[i]
            a,b=random.choice(PAIRS)
            oa,ob=seq[pi],seq[pj]
            seq[pi]=a;seq[pj]=b
        else:
            seq[i]=random.choice('ACGU')
        cur=''.join(seq)
        fc=RNA.fold_compound(cur)
        mfe,_=fc.mfe()
        nd=bp_dist_str(mfe)
        if nd<=d or random.random()<pow(2.718,-(nd-d)/T):
            d=nd
            if nd<bestd:
                bestd=nd;best=cur[:]
                if nd==0: return (best,0)
        else:
            if i in pair_idx:
                seq[pi]=oa;seq[pj]=ob
            else:
                seq[i]=old
        T*=0.9998
    return (best,bestd)

if __name__=='__main__':
    seed='GAGGAAAUUGAAUAGGCAAGAUGCAAGGAGUUCCUAUAUACACACGUUCGUUAGGACGCAAUAUGCUGUGUGAGUACAACGAUAGUUAGCGAAACGCGUACAAUAUUGGCUAAGAGCCCCUC'
    args=[(seed,t) for t in range(64)]
    with Pool(64) as p:
        results=p.map(run,args)
    results.sort(key=lambda x:x[1])
    best,dist=results[0]
    print('best dist',dist)
    print(best)
    fc=RNA.fold_compound(best)
    mfe,_=fc.mfe()
    print('mfe',mfe)
    print('tgt',s)
    print('match',mfe==s)
    # show top 5 dists
    for b,d in results[:5]:
        print('d',d)
